# Compare LSP notification sequences against the real local gopls without changing the engine.
import json
import hashlib
import os
from pathlib import Path
import subprocess
import sys
import threading

mode = os.environ.get('SEMEDIT_GOPLS_PROXY_MODE', 'control')
allowed = {'control', 'no_watched_change', 'no_save', 'change_only', 'change_only_save_trigger'}
if mode not in allowed:
    raise SystemExit('unknown proxy mode: ' + mode)
actual = '/Users/alessandro/sources/semantic-editor/.scratch/go/bin/gopls-go127'
child = subprocess.Popen([actual, *sys.argv[1:]], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=sys.stderr.buffer)
lock = threading.Lock()
counts = {'mode': mode, 'forwarded': {}, 'dropped': {}, 'published_notifications': 0, 'published_diagnostics': 0, 'diagnostic_sets': {}, 'state_file_counts': {}}
pending = {}
opened = set()
source_hashes = {}
state_cache = None
module_path = str(Path.cwd().resolve())
module_uri = Path(module_path).as_uri()

def normalize(value):
    if isinstance(value, str):
        return value.replace(module_uri, '$MODULE').replace(module_path, '$MODULE')
    if isinstance(value, list):
        return [normalize(item) for item in value]
    if isinstance(value, dict):
        return {key: normalize(item) for key, item in value.items()}
    return value

def source_state():
    global state_cache
    if state_cache is None:
        state_cache = hashlib.sha256(json.dumps(source_hashes, sort_keys=True).encode()).hexdigest()
    return state_cache

def frame(stream):
    headers = {}
    while True:
        line = stream.readline()
        if not line:
            return None
        if line in (b'\r\n', b'\n'):
            break
        key, value = line.decode('ascii').split(':', 1)
        headers[key.lower().strip()] = value.strip()
    size = int(headers['content-length'])
    payload = stream.read(size)
    if len(payload) != size:
        raise EOFError('truncated LSP frame')
    return json.loads(payload)

def write(stream, message):
    payload = json.dumps(message, separators=(',', ':'), ensure_ascii=False).encode()
    stream.write(f'Content-Length: {len(payload)}\r\n\r\n'.encode() + payload)
    stream.flush()

def record(category, method):
    with lock:
        values = counts[category]
        values[method] = values.get(method, 0) + 1

def save_counts():
    directory = Path(os.environ['SEMEDIT_GOPLS_PROXY_LOGDIR'])
    target = directory / f'{mode}-{os.getpid()}.json'
    temporary = target.with_suffix('.tmp')
    with lock:
        snapshot = json.dumps(counts, indent=2)
    with temporary.open('w') as output:
        output.write(snapshot + '\n')
        output.flush()
        os.fsync(output.fileno())
    temporary.replace(target)

def receive():
    try:
        while True:
            message = frame(child.stdout)
            if message is None:
                return
            method = message.get('method')
            if method == 'textDocument/publishDiagnostics':
                with lock:
                    counts['published_notifications'] += 1
                    counts['published_diagnostics'] += len(message.get('params', {}).get('diagnostics', []))
            request = None
            if 'id' in message and 'method' not in message:
                with lock:
                    request = pending.pop(str(message['id']), None)
            if request is not None and request[0] == 'textDocument/diagnostic' and 'result' in message:
                items = [json.dumps(normalize(item), sort_keys=True) for item in message['result'].get('items', [])]
                digest = hashlib.sha256(json.dumps(sorted(items)).encode()).hexdigest()
                with lock:
                    counts['diagnostic_sets'].setdefault(request[2], {})[request[1]] = digest
                    counts['state_file_counts'][request[2]] = request[3]
            if request is not None and request[0] == 'shutdown':
                save_counts()
            write(sys.stdout.buffer, message)
    except BrokenPipeError:
        return

receiver = threading.Thread(target=receive, daemon=True)
receiver.start()
try:
    while True:
        message = frame(sys.stdin.buffer)
        if message is None:
            break
        method = message.get('method', '<response>')
        params = message.get('params', {})
        uri = params.get('textDocument', {}).get('uri')
        if method == 'textDocument/didOpen':
            opened.add(uri)
            source_hashes[normalize(uri)] = hashlib.sha256(params['textDocument']['text'].encode()).hexdigest()
            state_cache = None
        if method == 'textDocument/didClose':
            opened.discard(uri)
            source_hashes.pop(normalize(uri), None)
            state_cache = None
        if method == 'textDocument/didChange':
            changes = params.get('contentChanges', [])
            if len(changes) != 1 or 'range' in changes[0]:
                raise RuntimeError('experiment expects full-content synchronization')
            source_hashes[normalize(uri)] = hashlib.sha256(changes[0]['text'].encode()).hexdigest()
            state_cache = None
        if method == 'initialize' and mode == 'change_only_save_trigger':
            params.setdefault('initializationOptions', {})['diagnosticsTrigger'] = 'Save'
        if method == 'textDocument/didSave' and mode in {'no_save', 'change_only', 'change_only_save_trigger'}:
            record('dropped', method)
            continue
        if method == 'workspace/didChangeWatchedFiles' and mode in {'no_watched_change', 'change_only', 'change_only_save_trigger'}:
            original = params.get('changes', [])
            kept = [change for change in original if not (change.get('type') == 2 and change.get('uri') in opened and change.get('uri', '').endswith('.go'))]
            if len(kept) != len(original):
                record('dropped', method)
            if not kept:
                continue
            params['changes'] = kept
        if 'id' in message and 'method' in message:
            with lock:
                pending[str(message['id'])] = (method, normalize(uri), source_state(), len(opened))
        record('forwarded', method)
        write(child.stdin, message)
finally:
    child.stdin.close()
    try:
        child.wait(timeout=5)
    except subprocess.TimeoutExpired:
        child.terminate()
        child.wait(timeout=5)
    receiver.join(timeout=5)

